import triton
import triton.language as tl


@triton.jit
def _hinge_none_kernel(x_ptr, y_ptr, out_ptr, margin, N, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < N
    x = tl.load(x_ptr + offs, mask=mask, other=0.0).to(tl.float32)
    y = tl.load(y_ptr + offs, mask=mask, other=0.0).to(tl.float32)
    # l = (y != 1 ? max(m - x, 0) : 0) + (y != -1 ? x : 0)
    term_margin = tl.where(y != 1.0, tl.maximum(margin - x, 0.0), 0.0)
    term_self = tl.where(y != -1.0, x, 0.0)
    loss = term_margin + term_self
    tl.store(out_ptr + offs, loss, mask=mask)


@triton.jit
def _hinge_reduce_stage1_kernel(
    x_ptr, y_ptr, partial_ptr, margin, N, BLOCK: tl.constexpr, NATIVE: tl.constexpr
):
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    # Vector accumulator: add each tile into fp32 lanes and do a single
    # tree-reduction at the end, instead of reducing every loop iteration.
    acc_vec = tl.zeros((BLOCK,), dtype=tl.float32)
