    stride = nprog * BLOCK
    offs0 = tl.arange(0, BLOCK)
    cur = start
    while cur < N:
        offs = cur + offs0
        mask = offs < N
        if NATIVE:
            # Compute the elementwise loss in the operand dtype (fewer/narrower
            # vector-ALU ops on fp16/bf16), then upcast only the result for the
            # error-sensitive fp32 accumulation.
            x = tl.load(x_ptr + offs, mask=mask, other=0.0)
            y = tl.load(y_ptr + offs, mask=mask, other=0.0)
            m = margin.to(x.dtype)
