@triton.jit
def _hinge_reduce_stage2_kernel(partial_ptr, out_ptr, P, scale, BLOCK: tl.constexpr):
    offs = tl.arange(0, BLOCK)
    mask = offs < P
    p = tl.load(partial_ptr + offs, mask=mask, other=0.0)
