def _canon_reduction(reduction):
    # Normalize both string and integer-enum forms to 'none'/'mean'/'sum'.
    # PyTorch enum: 0 -> none, 1 -> mean, 2 -> sum.
    if isinstance(reduction, str):
        return reduction
    r = int(reduction)
    if r == 0:
        return "none"
    if r == 1:
        return "mean"
    if r == 2:
        return "sum"
    raise ValueError(f"invalid reduction enum: {reduction}")


def hinge_embedding_loss(input, target, margin=1.0, reduction="mean"):
    x = input.contiguous()
    y = target.contiguous()
    N = x.numel()
    red = _canon_reduction(reduction)

    if red == "none":
        out = torch.empty_like(x)
        if N == 0:
            return out.view_as(input)
        BLOCK = 4096 if N >= (1 << 20) else 1024
        grid = (triton.cdiv(N, BLOCK),)
        _hinge_none_kernel[grid](x, y, out, float(margin), N, BLOCK=BLOCK)
        return out.view_as(input)

    # reduction == 'sum' or 'mean'
    out = torch.empty((), dtype=x.dtype, device=x.device)
    if N == 0:
        # mean of empty -> NaN (reference behavior); sum of empty -> 0
        if red == "mean":
            out.fill_(float("nan"))
        else:
            out.fill_(0.0)
        return out

    # Keep the narrow tile (matching the reference summation order) for small
    # inputs; widen it for large inputs where throughput dominates.
    BLOCK = 4096 if N >= (1 << 20) else 1024
    n_tiles = triton.cdiv(N, BLOCK)
    P = min(n_tiles, 2048)
    partial = torch.empty(P, dtype=torch.float32, device=x.device)
    # Use the native-dtype elementwise path only for large fp16 inputs, which
    # measured as vector-compute bound and benefited from narrower ALU ops.
    # bf16 regressed on this path and fp32/small-N keep the fp32-compute path.
    native = (x.dtype == torch.float16) and (N >= (1 << 20))
    _hinge_reduce_stage1_kernel[(P,)](
        x, y, partial, float(margin), N, BLOCK=BLOCK, NATIVE=native
    )

    scale = 1.0 / N if red == "mean" else 1.0
    BLOCK2 = triton.next_power_of_2(P)
    _hinge_reduce_stage2_kernel[(1,)](partial, out, P, float(scale), BLOCK=BLOCK2)
    return out
